// AUTO-GERADO a partir de um GeoJSON dos estados do Brasil (IBGE/simplificado).
// Mapa embutido (offline) usado no heatmap de agendamentos por cidade.
// Projeção equiretangular; use project(lng, lat) para posicionar pontos no mesmo espaço.

export const MAP_W = 560
export const MAP_H = 529

const LNG_MIN = -74.2
const LNG_MAX = -32.2
const LAT_MIN = -34.1
const LAT_MAX = 5.6

/** Converte (longitude, latitude) → coordenadas do viewBox do mapa. */
export function project(lng: number, lat: number): [number, number] {
  const x = ((lng - LNG_MIN) / (LNG_MAX - LNG_MIN)) * MAP_W
  const y = ((LAT_MAX - lat) / (LAT_MAX - LAT_MIN)) * MAP_H
  return [x, y]
}

